import { describe, it, vi } from 'vitest'
import { render, screen } from '@testing-library/react'
import { promises as fs } from 'fs'
import Home from './page'
import type { ProductGroup } from '@/lib/types'

vi.mock('@/components/header', () => ({
  __esModule: true,
  default: () => <div data-testid="header" />,
}))

vi.mock('@/components/block', () => ({
  __esModule: true,
  default: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}))

function time(label: string, fn: () => unknown) {
  const t0 = performance.now()
  const out = fn()
  const ms = performance.now() - t0
  // eslint-disable-next-line no-console
  console.log(`${label.padEnd(46)} ${ms.toFixed(0)}ms`)
  return out
}

describe('perf probe', () => {
  it('measures each step', async () => {
    const catalogue: ProductGroup[] = time('read categories.json', () =>
      JSON.parse(require('fs').readFileSync(`${process.cwd()}/public/categories.json`, 'utf8')),
    ) as ProductGroup[]
    const product = catalogue[0].products[0]
    const slug = product.slug ?? product.id

    const tree = await time('await Home()', () => Home()) as React.ReactElement
    const { container } = time('render(tree)', () => render(tree)) as { container: HTMLElement }

    // eslint-disable-next-line no-console
    console.log(`DOM elements: ${container.querySelectorAll('*').length}`)

    time('getByRole(link, {name})', () => screen.getByRole('link', { name: product.name }))
    time('getByRole(link, {name}) again', () => screen.getByRole('link', { name: product.name }))
    time('getByRole(link, {name, hidden:true})', () =>
      screen.getByRole('link', { name: product.name, hidden: true }),
    )
    time('getAllByRole(link) no name', () => screen.getAllByRole('link'))
    time('getAllByRole(link, hidden:true) no name', () => screen.getAllByRole('link', { hidden: true }))
    const el = time('querySelector a[href]', () =>
      container.querySelector(`a[href="/products/${slug}"]`),
    ) as HTMLElement | null
    // eslint-disable-next-line no-console
    console.log(`located: ${el ? el.tagName : 'NULL'} href=${el?.getAttribute('href')}`)
    if (el) {
      const { computeAccessibleName } = await import('dom-accessibility-api')
      time('computeAccessibleName(el)', () => computeAccessibleName(el))
    }
    time('getComputedStyle over every element', () => {
      let n = 0
      for (const e of Array.from(container.querySelectorAll('*'))) {
        if (window.getComputedStyle(e).visibility) n++
      }
      return n
    })
  })
})

import { describe, it, vi } from 'vitest'
import { render, screen } from '@testing-library/react'
import { promises as fs } from 'fs'
import Home from './page'
import type { ProductGroup } from '@/lib/types'

vi.mock('@/components/header', () => ({
  __esModule: true,
  default: () => <div data-testid="header" />,
}))

vi.mock('@/components/block', () => ({
  __esModule: true,
  default: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}))

function time(label: string, fn: () => unknown) {
  const t0 = performance.now()
  fn()
  const ms = performance.now() - t0
  // eslint-disable-next-line no-console
  console.log(`${label.padEnd(52)} ${ms.toFixed(0)}ms`)
}

describe('what is actually expensive', () => {
  it('pays the cost on a three-element DOM, before the page exists', async () => {
    const tiny = render(<a href="/x">hello</a>)
    // eslint-disable-next-line no-console
    console.log(`tiny DOM elements: ${document.body.querySelectorAll('*').length}`)

    time('FIRST getComputedStyle on a 1-element DOM', () =>
      window.getComputedStyle(tiny.container.querySelector('a')!).visibility,
    )
    time('getByRole(link,{name}) on the tiny DOM', () =>
      screen.getByRole('link', { name: 'hello' }),
    )

    tiny.unmount()

    const catalogue: ProductGroup[] = JSON.parse(
      await fs.readFile(`${process.cwd()}/public/categories.json`, 'utf8'),
    )
    const product = catalogue[0].products[0]
    time('render(await Home())', () => {})
    const tree = await Home()
    render(tree)
    // eslint-disable-next-line no-console
    console.log(`full DOM elements: ${document.body.querySelectorAll('*').length}`)

    time('getByRole(link,{name}) on the FULL page', () =>
      screen.getByRole('link', { name: product.name }),
    )
    time('getByRole(link,{name}) on the FULL page again', () =>
      screen.getByRole('link', { name: product.name }),
    )
  })
})

